interface PaymentProcessor { void charge(double amount); }

class PaymentProcessorFactory {
    // Type genuinely varies by runtime data -> factory earns its place.
    static PaymentProcessor forCountry(String country) {
        return switch (country) {
            case "US" -> new StripeProcessor();
            case "IN" -> new RazorpayProcessor();
            default   -> new PaypalProcessor();
        };
    }
}

var processor = PaymentProcessorFactory.forCountry(user.country());
processor.charge(order.total());
// And the simple DTO stays simple:
var dto = new UserDto(1L, "Asha"); // just use new
```

*Use Factory where the type or setup varies; use `new` where it doesn't.*

