// A single class decides everything. Adding a type EDITS this switch.
class ReportFactory {
    static ReportGenerator create(String fmt) {
        return switch (fmt) {
            case "pdf"   -> new PdfReportGenerator();
            case "excel" -> new ExcelReportGenerator();
            default -> throw new IllegalArgumentException(fmt);
        };
    }
}
