    void placeOrder(Order order) {
        var notifier = new EmailNotifier();   // hard dependency, closed seam
        notifier.send("Order " + order.getId()); // tests send REAL emails
    }
}
// You cannot replace EmailNotifier in a unit test without editing this code.
