@Configuration
class AppConfig {
    @Bean // a factory method: Spring calls it to create the bean
    PaymentProcessor paymentProcessor() { return new StripePaymentProcessor(); }

    @Bean
    NotificationService notificationService() {
        var s = new EmailNotificationService();
        s.setRetryCount(3); // factory handles complex init
        return s;
    }
}

@Service
class OrderService {
    private final PaymentProcessor processor;
    // The container (a factory) creates PaymentProcessor and injects it.
    OrderService(PaymentProcessor processor) { this.processor = processor; }
    void placeOrder(Order order) { processor.process(order.getTotal()); }
}

// The container resolves the whole graph for you:
var context = new AnnotationConfigApplicationContext(AppConfig.class);
var orderService = context.getBean(OrderService.class); // Factory in action
```

