```java
interface Button { } interface TextField { } interface ScrollBar { }

interface GUIFactory {                 // the abstract factory
    Button createButton();
    TextField createTextField();
    ScrollBar createScrollBar();
}

class WindowsGUIFactory implements GUIFactory {
    public Button createButton() { return new WindowsButton(); }
    public TextField createTextField() { return new WindowsTextField(); }
    public ScrollBar createScrollBar() { return new WindowsScrollBar(); }
}
class MacGUIFactory implements GUIFactory {
    public Button createButton() { return new MacButton(); }
    public TextField createTextField() { return new MacTextField(); }
    public ScrollBar createScrollBar() { return new MacScrollBar(); }
}

class UI {
    private final GUIFactory factory;
    UI(GUIFactory factory) { this.factory = factory; } // pick the family once
    void build() {
        var b = factory.createButton();
        var t = factory.createTextField(); // all from the SAME family
    }
}
// Swap WindowsGUIFactory -> MacGUIFactory: every component matches.
```

*The factory guarantees a consistent set — you can't accidentally mix platforms.*
